 77	    \Delta_{\text{T},\tau}(\bm{r})=\tau w \left(1+\omega^{\tau} e^{i\tau\bm{g}_2\cdot\bm{r}}+\omega^{2\tau} e^{i\tau\bm{g}_3\cdot\bm{r}} \right),
 78	\end{equation}
 79	where $w$ describes the tunneling strength, and $\omega=e^{i\frac{2\pi}{3}} $ following the $C_{3z}$ symmetry \cite{zhang2021spintextured}. The valley dependence of $ \Delta_{\text{T},\tau}$ is constrained by $\mathcal{T}$ symmetry. Here $ \Delta_{\text{T},\tau}$ couples states with opposite spins, which is symmetry allowed because the heterobilayer breaks the $z \rightarrow -z$  mirror symmetry. For parameters in $H_\tau$, we take $\psi_{\mathfrak{b}}=-14^{\circ}$ such that the potential maximum of $\Delta_{\mathfrak{b}}(\bm{r})$ is at the MM site \cite{zhang2021spintextured}; $V_{z\mathfrak{t}}$ is a parameter that is experimentally controllable by an applied out-of-plane displacement field; $V_{\mathfrak{b}}$ and $w$ are taken as theoretical parameters that can be adjusted to study different phases. We note that the interlayer tunneling 
 80	strength $w$ can be modified by pressure. 
 81	
 82	The low-energy moir\'e bands and their topology are tunable by $V_{z\mathfrak{t}}$. For the intrinsic band offset $V_{z\mathfrak{t}}$ that has a large negative value ($\sim -$ 110 meV) \cite{zhang2021spintextured}, the topmost moir\'e valence band at each valley mainly derives from the MoTe$_2$ layer and can be described by a tight-binding model on a triangular lattice, which is topologically trivial. By reducing $|V_{z\mathfrak{t}}|$ with an external displacement field, the energy gap between the topmost moir\'e valence bands derived respectively from MoTe$_2$ and WSe$_2$ can close and then reopen. This band inversion enabled by the tunneling term  $ \Delta_{\text{T},\tau}$ can lead to topological phase transitions. Figure~\ref{fig:1}(d) presents a topological phase diagram characterized by the valley-contrast Chern numbers $C_{\pm K}$ of the first moir\'e valence band in the parameter space of ($V_{z\mathfrak{t}}$, $w$). For $V_{z\mathfrak{t}}$ above the critical value, $C_{\pm K}$ become nontrivial with value ($\pm 1$). Figure~\ref{fig:1}(c) plots a representative moir\'e band structure in the topologically nontrivial regime of Fig.~\ref{fig:1}(d). Note that there is no overall energy gap that separates the first and second moir\'e valence bands in Fig.~\ref{fig:1}(c). The effect of many-body interaction on this gap is crucial as studied in the following.
 83	
 84	
 85	
 86	
 87	\begin{figure}[t]
 88	    \centering
 89	    \includegraphics[width=3.4in]{Fig2.pdf}
 90	    \caption{(a) Band structure from the HF calculation  at $\nu=2$ with the same parameters as Fig.~\ref{fig:1}(c). Orange (blue) lines show $+K$($-K$)-valley moir\'e bands. {The two horizontal dashed lines identify the charge gap at $\nu=2$.} Here $\epsilon=15$. (b) Charge gap at $\nu=2$ from the HF calculation as a function of $V_{z\mathfrak{t}}$ and $\epsilon$.  The gap vanishes at the dashed line, which separates phase I (topologically trivial insulators) and phase II ($\mathbb{Z}_2$ topological insulators). Here $w$=12 meV and $V_\mathfrak{b}$=7 meV.}
 44	\section{Single-particle Hamiltonian}
 45	
 46	The single-particle Hamiltonian in the second quantization formalism can be expressed as
 47	
 48	\begin{eqnarray}    &&\hat{\mathcal{H}}_0=\sum_{\tau={\pm}} \int d^2 \bm{r} \Psi_{\tau}^\dagger(\bm{r}) H_{\tau} \Psi_{\tau}(\bm{r}), \\
 49	    &&H_{\tau}=\begin{pmatrix}
 50	         -\frac{\hbar^2\bm{k}^2}{2m_\mathfrak{b}}+\Delta_{\mathfrak{b},\tau}(\bm{r}) &  \Delta_{\text{T},\tau}(\bm{r})\\
 51	        \Delta_{\text{T},\tau}^\dag(\bm{r}) & -\frac{\hbar^2\left(\bm{k}-\tau \bm{\kappa}\right)^2}{2m_\mathfrak{t}}+ \Delta_\mathfrak{t,\tau}(\bm{r})+V_{z\mathfrak{t}}
 52	    \end{pmatrix},\\
 53	    &&\Psi_{+}(\bm{r})=\begin{pmatrix}
 54	                    \psi_{\mathfrak{b},\uparrow,+}(\bm{r}) \\
 55	                    \psi_{\mathfrak{t},\downarrow,+}(\bm{r}) 
 56	                \end{pmatrix},  \quad
 57	    \Psi_{-}(\bm{r})=\begin{pmatrix}
 58	        \psi_{\mathfrak{b},\downarrow,-}(\bm{r}) \\
 59	        \psi_{\mathfrak{t},\uparrow,-}(\bm{r}) 
 60	    \end{pmatrix},
 61	\end{eqnarray}
 62	where $\tau=\pm $ represents $\pm K$ valleys, $\hbar \bm{k} = -i \hbar \partial_{\bm{r}}$ is the momentum operator, $\bm{\kappa}=\frac{4\pi}{3a_M}\left(1,0\right)$  is at a corner of the moir\'e Brillouin zone ({as shown in Fig.~\ref{fig:BZ}}), and $a_M$ is the moir\'e lattice constant. Note that the spin index of the fermion operators $\Psi_{\tau}$ is both layer and valley dependent.
 63	
 64	The Hamiltonian $\hat{\mathcal{H}}_0$ respects the time reversal symmetry $\mathcal{T}$, which is defined as  
 65	\begin{equation}\label{eq:Ham}
 66	    \hat{\mathcal{T}} \psi_{l,s,\tau}(\bm{r}) \hat{\mathcal{T}}^{-1} = - \sum_{s'}\epsilon_{ss'} \psi_{l,s',-\tau}(\bm{r}),\quad
 67	    \hat{\mathcal{T}} \psi_{l,s,\tau}^{\dagger}(\bm{r}) \hat{\mathcal{T}}^{-1} = - \sum_{s'}\epsilon_{ss'} \psi_{l,s',-\tau}^{\dagger}(\bm{r})
 68	     ,\quad 
 69	     \hat{\mathcal{T}}i\hat{\mathcal{T}}^{-1}=-i,
 70	\end{equation} 
 71	where $\hat{\mathcal{T}}$ is an antiunitary operator, the layer index $l=\{\mathfrak{b},\mathfrak{t}\}$ for the bottom and top layer, the spin index $s=\{\uparrow, \downarrow\}$ for spin up and down, and $\epsilon_{ss'}$ is the totally antisymmetric tensor with $\epsilon_{\uparrow \downarrow} = - \epsilon_{\downarrow \uparrow} =1$. Here the $\hat{\mathcal{T}}$ operation flips both spin and valley indices.
 72	By imposing the $\mathcal{T}$ symmetry $\hat{\mathcal{T}} \hat{\mathcal{H}}_0 \hat{\mathcal{T}}^{-1} = \hat{\mathcal{H}}_0$, we find the following constraints 
 73	\begin{equation}
 74	    \Delta_{l,-\tau}(\bm{r})=\Delta_{l,\tau}^*(\bm{r}), \quad 
 75	    \Delta_{\text{T},-\tau}(\bm{r})=-\Delta_{\text{T},\tau}^*(\bm{r}),
 76	\end{equation}
 77	Because the Hamiltonian $H_{\tau}$ is Hermitian, $\Delta_{l,\tau}(\bm{r})=\Delta_{l,\tau}^*(\bm{r})$. Therefore, $\Delta_{l,-}(\bm{r})=\Delta_{l,+}(\bm{r})$, and we can denote the intralayer potential simply as $\Delta_{l}(\bm{r})$ by dropping the valley index. For the interlayer tunneling at $+K$ valley $\Delta_{\text{T},+}(\bm{r})=w\left(1+\omega e^{i\bm{g}_2\cdot\bm{r}}+\omega^{2} e^{i\bm{g}_3\cdot\bm{r}} \right)$, we obtain the tunneling at $-K$ valley as $\Delta_{\text{T},-}(\bm{r})=-w\left(1+\omega^{-1} e^{-i\bm{g}_2\cdot\bm{r}}+\omega^{-2} e^{-i\bm{g}_3\cdot\bm{r}} \right)$, where $\omega=e^{i\frac{2\pi}{3}}$, and we assume $w$ takes a real value. The form of $\Delta_{T,+}(\bm{r})$ is determined by $C_{3z}$ (threefold rotation) symmetry.
 78	
 79	Parameters of the single-particle Hamiltonian $H_{\tau}$ have been obtained through density-functional-theory(DFT) band structure calculation~\cite{zhang2021spintextured}. However, the obtained parameters $(w, V_b)$ are of the order of meV, which are likely too small to be accurately estimated by DFT. Therefore, we treat $(w, V_b)$ as adjustable parameters. The main physical picture that we obtain in this work remains valid if we vary $(w, V_b)$, which we have checked numerically. In addition, these parameters could be tunable by pressure applied between layers.
 80	
 81	
 82	\begin{figure}[ht]
 83	    \centering
 84	    \includegraphics[width=3.4in]{Fig/BZ.pdf}
 85	    \caption{{A schematic illustration of the momentum space structure. The cyan and brown hexagons represent the  Brillouin zone of MoTe$_2$ (bottom layer) and WSe$_2$ (top layer), respectively. The small hexagon on the right (left) is the moir\'e Brillouin zone for $+K$ ($-K$) valley. Note that we use a different convention of the moir\'e Brillouin zone from that in Ref.~\cite{zhang2021spintextured} due to a gauge transformation which puts the center of the moir\'e Brillouin zone ($\gamma$ point) at the corner of the bottom layer Brillouin zone. We exaggerate the difference between MoTe$_2$ and WSe$_2$ Brillouin zones for illustration.}}
 86	    \label{fig:BZ}
 87	\end{figure}
 88	\section{Hartree-Fock calculation}
 89	In this section, we include the Coulomb interaction and derive the mean-field Hamiltonian by applying the Hartree-Fock (HF) approximation. We first rewrite $\hat{\mathcal{H}}_0$ in the momentum space with the creation operator being defined as $c_{\bm{k},l,\tau}^\dagger=\frac{1}{\sqrt{A}}\int \psi_{l,\tau}^\dagger(\bm{r}) e^{i \bm{k}\cdot \bm{r}} d^2 \bm{r}$ (the spin index is absent because it can be inferred from the valley and layer indices due to the effective spin-valley-layer locking), where $A$ is the total area. Thus, $\hat{\mathcal{H}}_0$ can be expressed as
 90	\begin{equation}
 91	    \hat{\mathcal{H}}_0=\sum_{\bm{k}_{\alpha},\bm{k}_{\beta}}\sum_{l_{\alpha},l_{\beta}}\sum_{\tau} h_{\bm{k}_{\alpha}l_{\alpha},\bm{k}_{\beta}l_{\beta}}^{(\tau)} c_{\bm{k}_{\alpha},l_{\alpha},\tau}^\dagger c_{\bm{k}_{\beta},l_{\beta},\tau},
 92	\end{equation}
 93	where $h^{(\tau)}$ is the Hamiltonian $H_{\tau}$ expanded in the plane-wave basis, and the momentum $\bm{k}$ is defined in the extended Brillouin zone {that spans the full momentum space, i.e., $\bm{k} \in \mathbb{R}^2$}. {Here, the subscripts $\alpha,\beta$ are index for momenta.} Due to Bloch's theorem, $h_{\bm{k}_{\alpha}l_{\alpha},\bm{k}_{\beta}l_{\beta}}^{(\tau)}$ is nonzero only when $\bm{k}_{\alpha}-\bm{k}_{\beta}$ is equal to {the linear combination of any multiples of hone of the moir\'e reciprocal lattice vectors (including the zero vector)}.
 94	
 95	At the charge neutrality (filling factor $\nu=0$) of the heterobilayer, all valence bands are below Fermi energy. We are interested in situations where the valence bands are slightly hole-doped. Therefore, it is convenient to study the many-body interaction in the hole basis.
 96	We define the hole operator as $b_{\bm{k},l,\tau}=c_{\bm{k},l,\tau}^\dagger$,  and $\hat{\mathcal{H}}_0$ in the hole basis is
 97	\begin{equation}
 98	    \hat{\mathcal{H}}_0 = \sum_\tau\Tr h^{(\tau)}-\sum_{\bm{k}_{\alpha},\bm{k}_{\beta}}\sum_{l_{\alpha},l_{\beta}}\sum_{\tau} [h^{(\tau)}]^{\intercal}_{\bm{k}_{\alpha}l_{\alpha},\bm{k}_{\beta}l_{\beta}} b_{\bm{k}_{\alpha},l_{\alpha},\tau}^\dagger b_{\bm{k}_{\beta},l_{\beta},\tau}
 99	\end{equation}
100	By combing the single-particle Hamiltonian with the hole-hole Coulomb interaction term, we obtain the full Hamiltonian (dropping the constant term) as

